mapper.select:
SELECT COUNT(*)
  FROM FAVORITE_DISEASE
 WHERE MEMBER_NO = #{memberNo}
   AND DISEASE_NO = #{diseaseNo}

mapper.delete:
DELETE FROM FAVORITE_DISEASE
 WHERE MEMBER_NO = #{memberNo}
   AND DISEASE_NO = #{diseaseNo}

